import{_ as r,o,c as t,a6 as a}from"./chunks/framework.BTqqHRil.js";const m=JSON.parse('{"title":"Tensor Operations","description":"","frontmatter":{},"headers":[],"relativePath":"libraries/tensor.md","filePath":"libraries/tensor.md","lastUpdated":null}'),s={name:"libraries/tensor.md"};function n(c,e,i,d,p,l){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="Tensor-Operations" tabindex="-1">Tensor Operations <a class="header-anchor" href="#Tensor-Operations" aria-label="Permalink to &quot;Tensor Operations {#Tensor-Operations}&quot;">​</a></h1><p><code>AMDGPU.jl</code> now provides wrappers for the <a href="https://rocm.docs.amd.com/projects/hipTensor/en/latest/index.html" target="_blank" rel="noreferrer"><code>hipTensor</code></a> library, which can be used to perform operations on high-dimensional arrays. However, there are some caveats:</p><ul><li><p><code>hipTensor</code> isn&#39;t supported on every AMD GPU. You can find the list of supported GPUs <a href="https://rocm.docs.amd.com/projects/hipTensor/en/latest/api-reference/api-reference.html#supported-gpu-architectures" target="_blank" rel="noreferrer">at the <code>hipTensor</code> documentation</a>.</p></li><li><p>for <a href="https://rocm.docs.amd.com/projects/hipTensor/en/latest/api-reference/api-reference.html#hiptensorcreateelementwisetrinary" target="_blank" rel="noreferrer"><code>hiptensorCreateElementwiseTrinary</code></a>, <code>hipTENSOR</code> 2.2 has the two binary operators the wrong way round: it applies the operator passed as <code>opABC</code> to <code>A</code> and <code>B</code>, and the one passed as <code>opAB</code> to that intermediate result and <code>C</code>. This is currently handled by our wrapper.</p></li><li><p>Unlike NVIDIA&#39;s <code>cuTENSOR</code>, <code>hipTENSOR</code> wants a <em>complex</em> compute descriptor for complex operands: pairing e.g. <code>ComplexF32</code> tensors with <code>HIPTENSOR_COMPUTE_DESC_32F</code> makes <code>hiptensorCreatePlan</code> fail with <code>HIPTENSOR_STATUS_EXECUTION_FAILED</code></p></li></ul>',3)])])}const _=r(s,[["render",n]]);export{m as __pageData,_ as default};
